examples.code:
body {
  /* ноль запросов к сети, родной вид на каждой ОС */
  font-family: system-ui, -apple-system, "Segoe UI", Roboto,
               "Helvetica Neue", Arial, sans-serif;
}

code, pre {
  font-family: "Cascadia Code", "JetBrains Mono", "SF Mono",
               Consolas, "Liberation Mono", monospace;
}

.hint {
  color: #22d3ee;
  border-left: 3px solid currentColor; /* рамка всегда в цвет текста */
}

exercises.starter:
.title {
  /* кегль, насыщенность, межстрочный интервал, межбуквенный */
}

.kicker {
  /* капс и разреженный межбуквенный интервал */
}

exercises.solution:
.title {
  font-size: 40px;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -1px;
}

.kicker {
  text-transform: uppercase;
  letter-spacing: 2px;
}

exercises.starter:
.chip {
  /* фон hex, текст rgb, обводка hsl */
}

.note {
  /* цвет подписи */
}

exercises.solution:
.chip {
  background-color: #6366f1;
  color: rgb(255, 255, 255);
  border: 1px solid hsl(240, 100%, 70%);
}

.note {
  color: #a3adcb;
}
